"""Managed .gitignore block for NWOB-initialized projects."""

from __future__ import annotations

from pathlib import Path

MARKER_START = "# nwob:gitignore:start — managed by nwob init/doctor; do not edit inside"
MARKER_END = "# nwob:gitignore:end"

MANAGED_BLOCK = """\
# nwob:gitignore:start — managed by nwob init/doctor; do not edit inside
# NWOB local install output (regenerated by init/doctor/persona switch)
.cursor/**
!.cursor/rules/
!.cursor/rules/constitution-custom.mdc
.nwob/
nwob-references/
AGENTS.md
/agents/
setup-nwob.sh
# nwob:gitignore:end
"""


def _managed_block_text() -> str:
    return MANAGED_BLOCK.rstrip("\n") + "\n"


def _compose_gitignore(before: str, after: str) -> str:
    """Merge user content around the canonical managed block."""
    block = _managed_block_text().rstrip("\n")
    parts: list[str] = []
    prefix = before.rstrip("\n")
    suffix = after.lstrip("\n").rstrip("\n")
    if prefix:
        parts.append(prefix)
    parts.append(block)
    if suffix:
        parts.append(suffix)
    return "\n\n".join(parts) + "\n"


def ensure_gitignore(project: Path) -> str | None:
    """Create or upsert the NWOB-managed .gitignore block.

    Returns the relative path ``.gitignore`` when created or updated, else ``None``.
    """
    project = project.resolve()
    gitignore = project / ".gitignore"

    if not gitignore.exists():
        gitignore.write_text(_managed_block_text(), encoding="utf-8")
        return ".gitignore"

    content = gitignore.read_text(encoding="utf-8")
    if MARKER_START in content and MARKER_END in content:
        before = content[: content.index(MARKER_START)]
        after = content[content.index(MARKER_END) + len(MARKER_END) :]
        new_content = _compose_gitignore(before, after)
        if new_content == content:
            return None
        gitignore.write_text(new_content, encoding="utf-8")
        return ".gitignore"

    new_content = _compose_gitignore(content, "")
    gitignore.write_text(new_content, encoding="utf-8")
    return ".gitignore"
